#!/bin/sh
# Writes infra/local/.env (gitignored) with fresh random credentials for the local stack,
# so no password, secret or token is ever committed. Leaves an existing .env alone.
set -eu
ENV_FILE="$(cd "$(dirname "$0")" && pwd)/.env"
if [ -f "$ENV_FILE" ]; then
  echo "$ENV_FILE exists; delete it (and run 'down -v') to generate new credentials"
  exit 0
fi
random() { openssl rand -hex 24; }
umask 077
cat > "$ENV_FILE" <<ENV
# Generated by init-env.sh for this machine only. Never commit or reuse these values.
POSTGRES_PASSWORD=$(random)
API_DB_PASSWORD=$(random)
INDEXER_DB_PASSWORD=$(random)
S3_ACCESS_KEY=gf$(openssl rand -hex 8)
S3_SECRET_KEY=$(random)
BAO_TOKEN=$(random)
ENV
echo "wrote $ENV_FILE"
